mapper.select:
SELECT C_IDX, C_NAME, C_LOGO, C_INDUSTRY, C_EST, C_INTRO, C_NUMBER, C_BUSINESS, C_REGISTER FROM COMPANY WHERE C_STATUS = 'NORMAL'
AND ( C_NAME LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY C_IDX DESC LIMIT #{page} OFFSET #{offset}

SELECT IFNULL(COUNT(1), 0)
FROM REVIEW
WHERE R_C_IDX = #{r_c_idx}

SELECT IFNULL(ROUND(SUM(R_STAR)/COUNT(R_STAR),1),0) as STAR
FROM REVIEW
WHERE R_C_IDX = #{r_c_idx}

SELECT COUNT(1) AS COUNT
FROM REVIEW
WHERE R_U_IDX =#{r_u_idx}
